#!/bin/bash

# Parse command line arguments
INCLUDE_GIT_IGNORE=false
while [[ $# -gt 0 ]]; do
    case $1 in
        --git)
            INCLUDE_GIT_IGNORE=true
            shift
            ;;
        *)
            echo "Unknown option: $1"
            echo "Usage: $0 [--git]"
            exit 1
            ;;
    esac
done

# Function to build find exclude arguments from ignore file
build_find_excludes() {
    local ignore_file="$1"
    local excludes=""
    
    if [[ -f "$ignore_file" ]]; then
        while IFS= read -r line; do
            # Skip empty lines and comments
            [[ -z "$line" || "$line" =~ ^# ]] && continue
            
            # Trim whitespace
            line=$(echo "$line" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')
            
            # Convert gitignore patterns to find patterns
            if [[ "$line" == /* ]]; then
                # Absolute path (starts with /)
                if [[ "$line" == */ ]]; then
                    # Absolute directory
                    excludes+=" -o -path \".${line%/}/*\""
                else
                    # Absolute file or directory
                    excludes+=" -o -path \".${line}\" -o -path \".${line}/*\""
                fi
            elif [[ "$line" == */ ]]; then
                # Relative directory pattern
                excludes+=" -o -path \"*/${line%/}/*\""
            elif [[ "$line" == *.* ]]; then
                # File extension or specific file
                excludes+=" -o -name \"$line\""
            else
                # General pattern (could be file or directory)
                excludes+=" -o -name \"$line\" -o -path \"*/$line/*\""
            fi
        done < "$ignore_file"
    fi
    
    echo "$excludes"
}

# Build find command with excludes
find_cmd="find . -type f"

# Always include .prompt.ignore patterns
prompt_excludes=$(build_find_excludes ".prompt.ignore")
if [[ -n "$prompt_excludes" ]]; then
    # Add the exclusion with proper syntax
    find_cmd+=" -not \( ${prompt_excludes:4}"
    needs_closing_paren=true
else
    needs_closing_paren=false
fi

# Optionally include gitignore patterns
if [[ "$INCLUDE_GIT_IGNORE" == true ]]; then
    # Local gitignore
    git_excludes=$(build_find_excludes ".gitignore")
    if [[ -n "$git_excludes" ]]; then
        if [[ "$needs_closing_paren" == false ]]; then
            find_cmd+=" -not \( ${git_excludes:4}"
            needs_closing_paren=true
        else
            find_cmd+="$git_excludes"
        fi
    fi
    
    # Global gitignore
    global_gitignore=$(git config --global core.excludesfile 2>/dev/null)
    if [[ -n "$global_gitignore" && -f "$global_gitignore" ]]; then
        global_excludes=$(build_find_excludes "$global_gitignore")
        if [[ -n "$global_excludes" ]]; then
            if [[ "$needs_closing_paren" == false ]]; then
                find_cmd+=" -not \( ${global_excludes:4}"
                needs_closing_paren=true
            else
                find_cmd+="$global_excludes"
            fi
        fi
    fi
fi

# Close the exclusion parenthesis if needed
if [[ "$needs_closing_paren" == true ]]; then
    find_cmd+=" \)"
fi

find_cmd+=" -print0"

# Define an empty string to hold the result
result=$'Consider the following source code:\n'

# Use a while loop to read the find output line by line
while IFS= read -r -d $'\0' file; do
    # remove trailing ./ from the filename
    file="${file#./}"

    # Use sed to remove the license text and append the modified file contents to the result string
    modified_content=$(cat "$file")

    result+="
${file}:
\`\`\`\`
$modified_content
\`\`\`\`
"
done < <(eval "$find_cmd")

# Pipe the result into pbcopy
echo "$result" | pbcopy
